mapper.insert:
INSERT INTO recommend_feedback (
user_id, session_id, item_id, action, rating, reason, created_at
) VALUES (
#{userId}, #{sessionId}, #{itemId}, #{action}, #{rating}, #{reason}, NOW()
)

mapper.select:
SELECT id, user_id, session_id, item_id, action, rating, reason, created_at FROM recommend_feedback WHERE user_id = #{userId} AND created_at >= #{startAt} AND created_at < #{endAt}
AND session_id IN
#{sessionId}
AND 1 = 0
ORDER BY created_at DESC, id DESC

SELECT item_id, SUM( CASE action WHEN 'SELECT' THEN 3.0 WHEN 'ADOPT' THEN 3.0 WHEN 'LIKE' THEN 2.0 WHEN 'DISLIKE' THEN -3.0 WHEN 'SKIP' THEN -1.0 WHEN 'RATING' THEN LEAST(2.0, GREATEST(-2.0, COALESCE(rating, 3) - 3.0)) ELSE 0.0 END ) AS feedback_score FROM recommend_feedback WHERE user_id = #{userId} AND item_id IS NOT NULL AND item_id IN
#{itemId}
GROUP BY item_id
